  LanguageConfig_AssistanceSystemIntroduction_CN = {
    Text = "·ผู้พิทักษ์สามารถเลือกผู้ปลุกตื่น 1 คนเพื่อช่วยในการต่อสู้ ผู้พิทักษ์อื่นๆ ที่ติดตามกันสามารถใช้ผู้ปลุกตื่นช่วยเหลือในการต่อสู้ที่ซากปรักหักพังแห่งการหลอมกร่อน บันทึกต้องห้าม และความฝันลึกซึ้งได้\n·ทุกครั้งที่ผู้พิทักษ์อื่นใช้ผู้ปลุกตื่นช่วยเหลือของคุณในการสำรวจสำเร็จ คุณจะได้รับรางวัล「คูปองกุหลาบทอง」×1000 โดยสามารถรับรางวัลได้สูงสุด 20 ครั้งต่อวัน\n·เมื่อรางวัลคูปองกุหลาบทองสะสมถึง 50 ครั้ง ผู้พิทักษ์ต้องรับรางวัลก่อนจึงจะสามารถรับรางวัลช่วยเหลือได้ต่อไป."
