  LanguageConfig_BPRuleTxt2_CN = {
    Text = "\n\n<Title:【หัวข้อพิเศษ】>\n·ระยะเวลาของหัวข้อในครั้งนี้คือ {s1} - {s2} (GMT+8) ทำภารกิจให้สำเร็จเพื่อรับประสบการณ์ภารกิจเป็นสองเท่า ช่วยให้ระดับภารกิจเพิ่มขึ้นอย่างรวดเร็ว。"
